        if (velocity.z > 1.0f)
            velocity.z = 1.0f;
        if (click_start.state == CLICK_START_STATE_WAITING_FOR_START)
            velocity.z = 0.0f;
    }

    if (follow_state.active == 1) {
        Vector3* p_velocity = &velocity;
        float follow_speed = velocity.z;
        switch (follow_state.Traverse(follow_speed, *p_position, &velocity)) {
        case 1:
        case 3:
            if (follow_state.active == 1)
