            || game->LocFromPos(p_position)->tile_id
                == SUBLOC_TILE_RAMP_RIGHT_BRACE_RAISED
            || game->LocFromPos(p_position)->tile_id
                == SUBLOC_TILE_RAMP_LEFT_BRACE_RAISED
            || game->LocFromPos(p_position)->tile_id
                == SUBLOC_TILE_RAMP_RIGHT_BRACE_RAISED
            || game->LocFromPos(p_position)->tile_id
                == SUBLOC_TILE_RAMP_LEFT_BRACE_BACKPATCH
            || game->LocFromPos(p_position)->tile_id
