    } else {
        if (!completion_handoff_active) {
            if (completion_game->level_mode == 4) {
                float remaining =
                    (1.0f - (transform.position.z - completion_start) / velocity.z)
                    * 0.016666668f;
                stopwatch.Add(remaining);
